const H = Number(entrada?.alturaInicialM ?? 5.0);
const L = Number(entrada?.distanciaHorizontalM ?? 10.0);
const g = Number(entrada?.gravedadMps2 ?? 9.81);

const ys = [H, vars.y1, vars.y2, vars.y3, vars.y4, vars.y5, vars.y6, vars.y7, 0.0];
const N = ys.length - 1;
const dx = L / N;
const pts = ys.map((y, i) => ({ x: i * dx, y }));

// Conservación de la energía mecánica: v(y) = sqrt(2 * g * (H - y))
let tiempoTotal = 0.0;
let violacion = 0.0;
let rugosidad = 0.0;

for (let i = 0; i < N; i++) {
  const yA = ys[i];
  const yB = ys[i + 1];
  if (i > 0 && yA >= H - 0.02) violacion += (yA - H + 0.05) * 12.0;
  if (i < N - 1 && yB >= H - 0.02) violacion += (yB - H + 0.05) * 12.0;

  const hA = Math.max(0.0, H - yA);
  const hB = Math.max(0.0, H - yB);
  const vA = Math.sqrt(2.0 * g * hA);
  const vB = Math.sqrt(2.0 * g * hB);
  const ds = Math.hypot(dx, yB - yA);
  const vProm = 0.5 * (vA + vB);
  if (vProm < 0.05) {
    tiempoTotal += 15.0;
    violacion += 1.0;
  } else {
    tiempoTotal += ds / vProm;
  }
}

// Curvatura discreta acumulada (suavidad geométrica de la rampa)
for (let i = 1; i < N; i++) {
  rugosidad += Math.abs(ys[i + 1] - 2.0 * ys[i] + ys[i - 1]);
}

const tRecta = 2.0 * Math.hypot(L, H) / Math.max(0.1, Math.sqrt(2.0 * g * H));

return {
  fitness: [tiempoTotal, Math.max(0.05, rugosidad)],
  violacion,
  escena: {
    xlim: [-0.6, L + 0.8],
    ylim: [-3.2, H + 1.0],
    grid: true,
    titulo: `Braquistócrona: t = ${tiempoTotal.toFixed(3)} s (recta: ${tRecta.toFixed(2)} s)`,
    lineas: [
      { x1: 0, y1: H, x2: L, y2: 0, color: "rgba(148, 163, 184, 0.55)", grosor: 1.5, guiones: [6, 4] },
      { x1: 0, y1: 0, x2: L, y2: 0, color: "rgba(100, 116, 139, 0.3)", grosor: 1 }
    ],
    curvas: [
      { puntos: pts, color: violacion > 0 ? "#ef4444" : "#38bdf8", grosor: 3.2 }
    ],
    puntos: [
      { x: 0, y: H, r: 6, color: "#22c55e", etiqueta: `Inicio (${H} m)` },
      ...pts.slice(1, -1).map(p => ({ x: p.x, y: p.y, r: 3.5, color: "#7dd3fc" })),
      { x: L, y: 0, r: 6, color: "#f59e0b", etiqueta: "Meta" }
    ]
  }
};
